 const populateFilters=()=>{const rooms=[...new Set(states.map(roomOf))].sort((a,b)=>a.localeCompare(b)),types=[...new Set(states.map(x=>x.type).filter(Boolean))].sort((a,b)=>a.localeCompare(b));$('weatherStateRoom').replaceChildren(new Option('All assigned rooms',''),...rooms.map(x=>new Option(x,x)));$('weatherStateType').replaceChildren(new Option('All function-block types',''),...types.map(x=>new Option(x,x)))};
 const paint=()=>{const term=$('weatherStateSearch').value.trim().toLocaleLowerCase(),room=$('weatherStateRoom').value,type=$('weatherStateType').value,list=states.filter(x=>(!term||`${x.control} ${x.state} ${x.type} ${x.uuid} ${x.room} ${x.category}`.toLocaleLowerCase().includes(term))&&(!room||roomOf(x)===room)&&(!type||x.type===type));$('weatherStateOptions').innerHTML=list.map(x=>`<button type="button" class="weather-picker-option" data-weather-state-option="${esc(x.uuid)}"><span class="weather-option-state">${esc(x.state||'(unnamed state)')}</span><span class="weather-option-meta"><span><b>Assigned room</b> ${esc(roomOf(x))}</span><span><b>Category</b> ${esc(x.category||'Uncategorized')}</span><span><b>Control / function block</b> ${esc(lastControl(x))}</span><span><b>Control path</b> ${esc(x.control||'—')}</span><span><b>Function-block type</b> ${esc(x.type||'—')}</span><span><b>State UUID</b> <code>${esc(x.uuid)}</code></span></span></button>`).join('')||'<p class="notice">No matching states. Refresh discovery or change the filters.</p>';dlg.querySelectorAll('[data-weather-state-option]').forEach(option=>option.onclick=()=>{mapping.stateUuid=option.dataset.weatherStateOption;const selected=states.find(x=>x.uuid===mapping.stateUuid);document.querySelector(`[data-weather-state="${field}"]`).innerHTML=`<strong>${esc(selected.state)}</strong><br>${esc(selected.room||'Unassigned')} · ${esc(selected.control)}<br><small>${esc(selected.type)}</small>`;dlg.close()})};
 $('weatherStateSearch').oninput=paint;$('weatherStateRoom').onchange=paint;$('weatherStateType').onchange=paint;$('weatherPickerClose').onclick=()=>dlg.close();
 $('weatherStateRefresh').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{const catalog=await api(`loxone/${mapping.serverId}/resources/refresh`,{method:'POST'});states=catalog.states||[];resources.loxone[mapping.serverId]=states;resources.loxoneDiscoveredAt[mapping.serverId]=catalog.discoveredAt;populateFilters();paint()}catch(error){showInfoToast(error.message,'error')}finally{button.disabled=false}};
 populateFilters();paint();dlg.addEventListener('close',()=>dlg.remove(),{once:true});dlg.showModal()
