function renderSourceStateOptions(){if(!mappingDraft)return;const select=mappingEditorPage.querySelector('#sourceState'),states=resources.loxone[mappingDraft.loxoneServerId]||[],term=(mappingEditorPage.querySelector('#sourceSearch')?.value||'').trim().toLocaleLowerCase(),selected=states.find(state=>state.uuid===mappingDraft.loxoneStateUuid),roomOf=state=>state.room||'Room metadata not loaded — refresh states',matches=states.filter(state=>(!editorSourceFilter.type||state.type===editorSourceFilter.type)&&(!editorSourceFilter.room||roomOf(state)===editorSourceFilter.room)&&(!term||`${state.room} ${state.category} ${state.control} ${state.state} ${state.type} ${state.uuid}`.toLocaleLowerCase().includes(term))),options=selected&&!matches.some(state=>state.uuid===selected.uuid)?[selected,...matches]:matches;select.replaceChildren(new Option(states.length?'Choose source state':'Discover states first',''));for(const state of options)select.add(new Option(`${state.state} · ${roomOf(state)} · ${state.control} · ${state.category||'Uncategorized'} (${state.type})`,state.uuid));select.value=mappingDraft.loxoneStateUuid||''}
function renderPipelineConverterSettings(c){if(c.type==='lookup')return `<p class="notice">Each exact numeric input maps to a typed output. Unmatched inputs fail safely.</p><div class="pipeline-rules">${(c.exactRules||[]).map((r,i)=>`<div class="pipeline-rule"><div class="field"><label>Input equals</label><input data-rule-input="${i}" type="number" step="any" value="${r.inputValue}" required></div><div class="field"><label>Output type</label><select data-rule-type="${i}"><option value="number" ${r.outputType==='number'?'selected':''}>Number</option><option value="boolean" ${r.outputType==='boolean'?'selected':''}>Boolean</option><option value="string" ${r.outputType==='string'?'selected':''}>Text</option></select></div><div class="field"><label>Output value</label><input data-rule-value="${i}" value="${esc(r.outputValue)}" required></div><button type="button" class="danger" data-rule-remove="${i}">×</button></div>`).join('')}</div><button type="button" class="secondary" id="addPipelineRule">Add rule</button>`;if(c.type==='range')return `<p class="notice">Inclusive limits; source values inside and outside the range can each produce a typed output.</p><div class="grid"><div class="field"><label>Minimum</label><input id="rangeMin" type="number" step="any" value="${c.rangeMinimum}" required></div><div class="field"><label>Maximum</label><input id="rangeMax" type="number" step="any" value="${c.rangeMaximum}" required></div></div><div class="grid">${renderPipelineOutput('inside',c.insideOutputType,c.insideOutputValue)}${renderPipelineOutput('outside',c.outsideOutputType,c.outsideOutputValue)}</div>`;return `<p class="notice">${c.type==='hsv'?'Parses Loxone hsv(h,s,v) and produces Hue RGB packed color.':c.type==='tunableWhite'?'Parses Loxone temp(brightness,kelvin) and produces Hue tunable-white value.':c.type==='onOff'?'Converts zero/nonzero to Boolean false/true.':c.type==='packedColor'?'Passes a numeric Loxone packed color to the target.':'Passes a numeric source value through unchanged.'}</p>`}
function renderPipelineOutput(name,type,value){return `<div><div class="field"><label>${name==='inside'?'Inside':'Outside'} output type</label><select data-range-type="${name}"><option value="number" ${type==='number'?'selected':''}>Number</option><option value="boolean" ${type==='boolean'?'selected':''}>Boolean</option><option value="string" ${type==='string'?'selected':''}>Text</option></select></div><div class="field"><label>Output value</label><input data-range-value="${name}" value="${esc(value)}" required></div></div>`}
function wirePipelineConverterSettings(container,c,rerender){container.querySelectorAll('[data-rule-input]').forEach(e=>e.oninput=()=>c.exactRules[+e.dataset.ruleInput].inputValue=Number(e.value));container.querySelectorAll('[data-rule-type]').forEach(e=>e.onchange=()=>c.exactRules[+e.dataset.ruleType].outputType=e.value);container.querySelectorAll('[data-rule-value]').forEach(e=>e.oninput=()=>c.exactRules[+e.dataset.ruleValue].outputValue=e.value);container.querySelectorAll('[data-rule-remove]').forEach(e=>e.onclick=()=>{c.exactRules.splice(+e.dataset.ruleRemove,1);rerender()});container.querySelector('#addPipelineRule')?.addEventListener('click',()=>{c.exactRules.push({inputValue:0,outputType:'string',outputValue:''});rerender()});container.querySelector('#rangeMin')?.addEventListener('input',e=>c.rangeMinimum=Number(e.target.value));container.querySelector('#rangeMax')?.addEventListener('input',e=>c.rangeMaximum=Number(e.target.value));container.querySelectorAll('[data-range-type]').forEach(e=>e.onchange=()=>c[e.dataset.rangeType==='inside'?'insideOutputType':'outsideOutputType']=e.value);container.querySelectorAll('[data-range-value]').forEach(e=>e.oninput=()=>c[e.dataset.rangeValue==='inside'?'insideOutputValue':'outsideOutputValue']=e.value)}
