function renderIrrigationDisableMapping(){const guide=$('irrigationLoxoneGuide');if(!guide||!cfg.irrigation)return;let section=$('irrigationDisableMapping');if(!section){guide.insertAdjacentHTML('beforeend','<section id="irrigationDisableMapping" class="irrigation-live"></section>');section=$('irrigationDisableMapping')}const saved=cfg.irrigation.irrigationDisabledState,serverId=irrigationDisableServerDraft||saved?.serverId||cfg.loxoneServers[0]?.id||'',selected=saved?.serverId===serverId?(resources.loxone[serverId]||[]).find(x=>x.uuid===saved.stateUuid):null;section.innerHTML=`<h3>Winter / system-emptying interlock</h3><p class="notice">Select a readable state for the existing switch that disables irrigation during winter or system draining. ON blocks new irrigation and forces Irrigation Required OFF; unknown or disconnected state fails closed. A running cycle is not interrupted; zero durations are written once the block is idle.</p><div class="grid"><div class="field"><label>Miniserver</label><select id="irrigationDisableServer"><option value="">Choose Miniserver</option>${cfg.loxoneServers.map(x=>`<option value="${esc(x.id)}" ${serverId===x.id?'selected':''}>${esc(x.name)}</option>`)}</select></div><div class="field"><label>Selected state</label><div>${selected?`<strong>${esc(selected.state)}</strong><br>${esc(selected.room||'Unassigned')} · ${esc(selected.control)}<br><small>${esc(selected.type)}</small>`:saved?.serverId===serverId&&saved.stateUuid?`${esc(saved.state||'Selected state')} · ${esc(saved.control)}`:'No state selected'}</div></div><div><button type="button" class="secondary" id="chooseIrrigationDisableState">Choose state</button></div></div><button type="button" id="saveIrrigationDisableState">Save interlock</button><span id="irrigationDisableMessage" class="notice" role="status"></span>`;const server=$('irrigationDisableServer');server.onchange=()=>{irrigationDisableServerDraft=server.value;renderIrrigationDisableMapping()};$('chooseIrrigationDisableState').onclick=()=>openIrrigationDisablePicker();$('saveIrrigationDisableState').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{if(!saved?.stateUuid||saved.serverId!==serverId)throw new Error('Choose the irrigation-disable state before saving.');await api('irrigation',{method:'PUT',body:JSON.stringify(readIrrigation())});$('irrigationDisableMessage').textContent='Saved. Irrigation stays disabled until a valid state arrives.';await refreshIrrigationDashboard()}catch(error){$('irrigationDisableMessage').textContent=error.message}finally{button.disabled=false}}}
async function openIrrigationDisablePicker(){const saved=cfg.irrigation.irrigationDisabledState,serverId=$('irrigationDisableServer')?.value||irrigationDisableServerDraft||saved?.serverId;if(!serverId){showInfoToast('Choose a Miniserver first.','error');return}let states=resources.loxone[serverId]||[];const dlg=document.createElement('dialog');dlg.className='weather-picker-dialog';dlg.innerHTML='<h2>Choose irrigation-disable state</h2><p class="notice">ON means irrigation is disabled. Choose the state of the existing winter/system-emptying switch.</p><div class="row"><input id="disableSearch" type="search" placeholder="Search state, room, control, category, UUID"><select id="disableRoom"><option value="">All rooms</option></select><select id="disableType"><option value="">All types</option></select><button id="disableRefresh" type="button" class="secondary">Refresh states</button></div><div id="disableOptions" class="weather-picker-list"></div><button id="disableClose" type="button" class="secondary">Cancel</button>';document.body.append(dlg);const roomOf=x=>x.room||'Room metadata not loaded',fill=()=>{const rooms=[...new Set(states.map(roomOf))].sort(),types=[...new Set(states.map(x=>x.type).filter(Boolean))].sort();$('disableRoom').replaceChildren(new Option('All rooms',''),...rooms.map(x=>new Option(x,x)));$('disableType').replaceChildren(new Option('All types',''),...types.map(x=>new Option(x,x)))};const paint=()=>{const term=$('disableSearch').value.toLowerCase(),room=$('disableRoom').value,type=$('disableType').value,list=states.filter(x=>(!term||`${x.state} ${x.room} ${x.control} ${x.category} ${x.type} ${x.uuid}`.toLowerCase().includes(term))&&(!room||roomOf(x)===room)&&(!type||type===x.type));$('disableOptions').innerHTML=list.map(x=>`<button type="button" class="weather-picker-option" data-disable-uuid="${esc(x.uuid)}"><span class="weather-option-state">${esc(x.state||'(unnamed state)')}</span><span class="weather-option-meta"><span><b>Room</b> ${esc(roomOf(x))}</span><span><b>Control</b> ${esc(x.control||'—')}</span><span><b>Category</b> ${esc(x.category||'—')}</span><span><b>Function-block type</b> ${esc(x.type||'—')}</span><span><b>UUID</b> <code>${esc(x.uuid)}</code></span></span></button>`).join('')||'<p class="notice">No states match. Refresh Loxone resources or change filters.</p>';dlg.querySelectorAll('[data-disable-uuid]').forEach(button=>button.onclick=()=>{const x=states.find(item=>item.uuid===button.dataset.disableUuid);cfg.irrigation.irrigationDisabledState={serverId,stateUuid:x.uuid,control:x.control,state:x.state};irrigationDisableServerDraft=serverId;renderIrrigationDisableMapping();dlg.close()})};$('disableSearch').oninput=paint;$('disableRoom').onchange=paint;$('disableType').onchange=paint;$('disableClose').onclick=()=>dlg.close();$('disableRefresh').onclick=async event=>{event.currentTarget.disabled=true;try{const catalog=await api(`loxone/${serverId}/resources/refresh`,{method:'POST'});states=catalog.states||[];resources.loxone[serverId]=states;fill();paint()}catch(error){showInfoToast(error.message,'error')}finally{event.currentTarget.disabled=false}};fill();paint();dlg.addEventListener('close',()=>dlg.remove(),{once:true});dlg.showModal()}
const dashboardWithInterlock=renderIrrigationDashboard;renderIrrigationDashboard=function(data){dashboardWithInterlock(data);const box=$('irrigationDashboard'),status=data.interlock;if(!box||!status)return;const summary=box.querySelector('.irrigation-summary-grid');if(summary){const card=document.createElement('article');card.className='irrigation-stat';card.innerHTML=`<span>Irrigation interlock</span><strong>${status.disabled?'DISABLED':'Allowed'}</strong><small>${esc(status.summary)}${status.lastReceivedAt?` · last state ${esc(irrigationDate(status.lastReceivedAt))}`:''}</small>`;summary.append(card)}const rec=summary?.querySelector('.irrigation-stat:nth-child(3) small');if(rec&&status.disabled)rec.textContent+=` · Outputs blocked by interlock; raw recommendation is diagnostic only.`;const heading=[...box.querySelectorAll('h3')].find(x=>x.textContent.includes('Persisted water balance'));if(heading){const factors=data.seasonalFactorsForLastBalancedMonth||{},rows=Object.entries(factors).map(([group,factor])=>`<tr><td>${esc(group)}</td><td>${Number(factor).toFixed(2)}</td></tr>`).join('');heading.insertAdjacentHTML('afterend',`<h3>Seasonal coefficients for month of last processed date (${esc(data.stored?.lastBalancedLocalDate||'current month fallback')})</h3><p class="notice">The listed factor scales ET₀ only when that date had complete weather coverage. Missing group profiles use 1.0; see the server debug log for the exact daily balance calculation.</p><div class="table-wrap"><table><thead><tr><th>Balance group</th><th>ET₀ factor</th></tr></thead><tbody>${rows||'<tr><td colspan="2">No configured groups</td></tr>'}</tbody></table></div>`)}};
if(token()){$('login').classList.add('hidden');$('app').classList.remove('hidden');load().catch(()=>{sessionStorage.removeItem('gatewayToken');location.reload()})}setInterval(()=>{if(token()&&!$('app').classList.contains('hidden'))refreshStatus()},10000);
